"""``python -m prismtrace.verify`` — prove credential and report live status.

Exit codes:
    0  credential OK (Tier A). Does **not** mean the app is sending live traces.
    1  doctor unreachable / stuck after credential OK
    2  the credential or arguments are wrong

Always print both:
    CREDENTIAL OK|FAIL
    LIVE CONNECTED|WAITING FOR LIVE

Agents and humans must read the LIVE line for framework success — exit 0 alone
is not "LangChain connected."
"""

from __future__ import annotations

import argparse
import os
import sys
import time
from typing import Any, Optional

import httpx

DEFAULT_POLL_ATTEMPTS = 10
DEFAULT_POLL_SECONDS = 3.0


def _fail(message: str, code: int = 2) -> int:
    print(f"CREDENTIAL FAIL — {message}", file=sys.stderr)
    print("WAITING FOR LIVE — credential not verified")
    return code


def handshake(
    client: httpx.Client, project_id: str, api_key: str, send_test_trace: bool = True
) -> tuple[bool, str, Optional[dict[str, Any]]]:
    """Validate the credential. Returns ``(ok, message, payload)``."""
    try:
        resp = client.post(
            "/api/setup-doctor/handshake",
            headers={"X-PRISMtrace-Key": api_key},
            json={
                "project_id": project_id,
                "send_test_trace": send_test_trace,
                "client": "prismtrace.verify",
            },
        )
    except Exception as exc:
        return False, f"could not reach the PRISMtrace host: {exc}", None

    if resp.status_code == 200:
        return True, resp.json().get("message", "credential valid"), resp.json()

    try:
        detail = resp.json().get("detail") or resp.text
    except Exception:
        detail = resp.text
    return False, f"HTTP {resp.status_code}: {detail}", None


def poll_doctor(
    client: httpx.Client,
    project_id: str,
    api_key: str,
    attempts: int = DEFAULT_POLL_ATTEMPTS,
    interval: float = DEFAULT_POLL_SECONDS,
) -> Optional[dict[str, Any]]:
    """Poll the doctor once per attempt; return the latest payload.

    Does not stop early on synthetic handshake traces — those are demo and
    must not count as live. Callers read ``live_connected`` from the payload.

    The doctor endpoint is authenticated like the handshake. Omitting the
    header made every poll 401 on auth-enforcing hosts, so the tool always
    ended in "WAITING FOR LIVE — the setup doctor could not be reached" even
    when everything worked.
    """
    latest: Optional[dict[str, Any]] = None
    for attempt in range(1, attempts + 1):
        try:
            resp = client.get(
                "/api/setup-doctor",
                params={"project_id": project_id},
                headers={"X-PRISMtrace-Key": api_key},
            )
            if resp.status_code != 200:
                print(f"  … doctor returned HTTP {resp.status_code}")
                time.sleep(interval)
                continue
            latest = resp.json()
        except Exception as exc:
            print(f"  … doctor unreachable ({exc})")
            time.sleep(interval)
            continue

        live = bool(latest.get("live_connected"))
        print(
            f"  … attempt {attempt}/{attempts}: overall={latest.get('overall')} "
            f"live_connected={live}"
        )
        if live:
            return latest
        if attempt < attempts:
            time.sleep(interval)
    return latest


def render(result: dict[str, Any], *, credential_ok: bool) -> int:
    symbols = {"done": "✓", "pending": "·", "unknown": "?"}
    print("\nPRISMtrace setup status")
    for step in result.get("steps", []):
        print(f"  {symbols.get(step['status'], '?')} {step['title']}: {step['detail']}")

    if credential_ok:
        print("\nCREDENTIAL OK — API key is valid for this project.")
    else:
        print("\nCREDENTIAL FAIL — API key was not verified.")

    live = bool(result.get("live_connected"))
    if live:
        n = result.get("live_trace_count")
        suffix = f" ({n} live)" if n is not None else ""
        print(f"LIVE CONNECTED — non-demo trace received{suffix}.")
    else:
        print(
            "WAITING FOR LIVE — no non-demo trace yet. "
            "Run your instrumented app once; handshake alone is not enough."
        )

    if not credential_ok:
        return 2
    # Exit 0 = credential OK. Agents must still report the LIVE line.
    return 0


def main(argv: Optional[list[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        prog="python -m prismtrace.verify",
        description=(
            "Validate the PRISMtrace API key and report whether live (non-demo) "
            "traces have arrived. Exit 0 means credential OK, not framework connected."
        ),
    )
    parser.add_argument("--host", default=os.getenv("PRISMTRACE_HOST"))
    parser.add_argument("--project-id", default=os.getenv("PRISMTRACE_PROJECT_ID"))
    parser.add_argument("--api-key", default=os.getenv("PRISMTRACE_API_KEY"))
    parser.add_argument("--attempts", type=int, default=DEFAULT_POLL_ATTEMPTS)
    parser.add_argument("--interval", type=float, default=DEFAULT_POLL_SECONDS)
    args = parser.parse_args(argv)

    if not args.host:
        return _fail("no host. Pass --host or set PRISMTRACE_HOST.")
    if not args.project_id:
        return _fail("no project id. Pass --project-id or set PRISMTRACE_PROJECT_ID.")
    if not args.api_key:
        return _fail("no API key. Pass --api-key or set PRISMTRACE_API_KEY.")

    host = args.host.rstrip("/")
    print(f"PRISMtrace verify -> {host}\n  project: {args.project_id}")

    with httpx.Client(base_url=host, timeout=30.0) as client:
        ok, message, _ = handshake(client, args.project_id, args.api_key)
        if not ok:
            return _fail(message)
        print(f"✓ {message}")

        result = poll_doctor(
            client, args.project_id, args.api_key, args.attempts, args.interval
        )
        if result is None:
            print("\nCREDENTIAL OK — API key is valid for this project.")
            print("WAITING FOR LIVE — the setup doctor could not be reached.")
            return 1
        return render(result, credential_ok=True)


if __name__ == "__main__":
    raise SystemExit(main())
